<script setup lang="ts">
import {computed,ref} from 'vue';import {useI18n} from 'vue-i18n';import {RouterLink,useRouter} from 'vue-router';import {BaseButton,BaseInput,BaseModal,EmptyState,ErrorState,LoadingState} from '@/shared/components/base';import {useToast} from '@/shared/toast/useToast';import {useCreateProjectMutation,useProjectsQuery} from '../queries'
const {t}=useI18n();const toast=useToast();const router=useRouter();const proposalId=ref('');const open=ref(false);const {data,isPending,isError,refetch}=useProjectsQuery(computed(()=>({page:1,page_size:20})));const create=useCreateProjectMutation();async function submit(){try{const item=await create.mutateAsync({proposal_id:proposalId.value,create_share_link:true});toast.success('projects.messages.created');await router.push({name:'project-detail',params:{id:item.id}})}catch(error){toast.errorFromUnknown(error)}}
</script><template><section class="w-full"><div class="flex items-end justify-between"><div><h1 class="font-display text-3xl text-ink">{{t('projects.title')}}</h1><p class="mt-2 text-muted">{{t('projects.subtitle')}}</p></div><BaseButton @click="open=true">{{t('projects.create')}}</BaseButton></div><LoadingState v-if="isPending" class="mt-8"/><ErrorState v-else-if="isError" class="mt-8" :title="t('common.errors.generic')" :retry-label="t('common.actions.retry')" @retry="refetch()"/><EmptyState v-else-if="!data?.results.length" class="mt-8" :title="t('projects.empty')"/><div v-else class="mt-8 space-y-3"><RouterLink v-for="item in data.results" :key="item.id" :to="`/app/projects/${item.id}`" class="block rounded-lg border border-border bg-canvas-elevated p-4"><p class="font-medium text-ink">{{item.title}}</p><p class="text-sm text-muted">{{item.status}}</p></RouterLink></div><BaseModal :open="open" :title="t('projects.create')" @close="open=false"><BaseInput v-model="proposalId" :label="t('projects.proposalId')"/><template #footer><BaseButton :loading="create.isPending.value" @click="submit">{{t('common.actions.create')}}</BaseButton></template></BaseModal></section></template>